// #43e90c הודעת אין הרשאה — экраны управления системой (admin компании) и управления аккаунтом (обычный user).
// Только просмотр, данных не создаётся.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';

const NO_PERMISSION = 'אין לך הרשאה למסך זה';
const SYSTEM_ADMINS_ONLY = 'המסך זמין למנהלי מערכת בלבד.';
const ACCOUNT_ADMINS_ONLY = 'המסך זמין למנהלי חשבון בלבד.';

test.describe('הודעת אין הרשאה — מסכי ניהול המערכת (מנהל חשבון)', () => {
  test.use({ storageState: authState('admin') });

  for (const route of ['/admin', '/admin/sources', '/admin/tenders', '/admin/faults']) {
    test(`${route}: מנהל חשבון רואה "זמין למנהלי מערכת בלבד" #43e90c @desktop @prod-safe`, async ({ page }) => {
      await page.goto(route);
      await expect(page.getByText(NO_PERMISSION, { exact: true })).toBeVisible();
      await expect(page.getByText(SYSTEM_ADMINS_ONLY, { exact: true })).toBeVisible();
      await expect(page.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toHaveCount(0);
    });
  }
});

test.describe('הודעת אין הרשאה — מסכי ניהול החשבון (משתמש רגיל)', () => {
  test.use({ storageState: authState('user') });

  for (const route of ['/users', '/users/invite', '/onboarding']) {
    test(`${route}: משתמש רגיל רואה "זמין למנהלי חשבון בלבד" #43e90c @desktop @prod-safe`, async ({ page }) => {
      await page.goto(route);
      await expect(page.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toBeVisible();
      await expect(page.getByText(SYSTEM_ADMINS_ONLY, { exact: true })).toHaveCount(0);
    });
  }
});
